#!/usr/bin/env node
// Characterizes slash-commands.mjs's runtime install/remove path (installPackageCommands/
// removePackageCommands), which resolves paths through provider path resolution. The
// build-time render
// path (renderSlashCommands/render-slash-commands.mjs) already has strong coverage via
// `scripts/doctor.sh`'s --check run against the real generated tree; this file covers the
// runtime path doctor doesn't touch: copying a package's already-generated wrapper into a live
// harness commands dir, and refusing to clobber a non-generated file.
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "roborepo-slash-commands-char-"));
try {
  process.env.ROBOREPO_APP_ROOT = repoRoot;
  const { installPackageCommands, removePackageCommands } = await import("../cli/slash-commands.mjs");

  const genDir = path.join(repoRoot, "generated", "packages", "__char_test_pkg__", "claude", "commands");
  fs.mkdirSync(genDir, { recursive: true });
  const marker = "<!-- Generated by scripts/build/render-slash-commands.mjs; do not edit directly. -->";
  fs.writeFileSync(
    path.join(genDir, "char-test-cmd.md"),
    `${marker}\n<!-- Owned by package: __char_test_pkg__ -->\n\n# /char-test-cmd\n\nHello.\n`,
  );

  const pkg = { id: "__char_test_pkg__", resources: [{ type: "slash-command", name: "char-test-cmd", harnesses: ["claude"] }] };
  const harnessHome = path.join(tmp, ".claude");
  fs.mkdirSync(harnessHome, { recursive: true });

  try {
    // --- Install: copies the generated wrapper into <home>/commands ---
    installPackageCommands(pkg, harnessHome, "claude");
    const installed = path.join(harnessHome, "commands", "char-test-cmd.md");
    assert.ok(fs.existsSync(installed), "installPackageCommands must copy the generated wrapper into the live commands dir");
    assert.match(fs.readFileSync(installed, "utf8"), /Hello\./, "installed content matches the generated source");

    // --- Install refuses to clobber a non-generated pre-existing file with the same name ---
    const collisionHome = path.join(tmp, ".claude-collision");
    fs.mkdirSync(path.join(collisionHome, "commands"), { recursive: true });
    fs.writeFileSync(path.join(collisionHome, "commands", "char-test-cmd.md"), "# user-owned, not generated\n");
    installPackageCommands(pkg, collisionHome, "claude");
    assert.match(
      fs.readFileSync(path.join(collisionHome, "commands", "char-test-cmd.md"), "utf8"),
      /user-owned, not generated/,
      "installPackageCommands must refuse to overwrite a non-generated live command file",
    );

    // --- Remove: deletes only the generated wrapper it owns ---
    removePackageCommands(pkg, harnessHome, "claude");
    assert.equal(fs.existsSync(installed), false, "removePackageCommands must remove the generated wrapper it installed");

    // --- Remove refuses to delete a non-generated file even if the name matches ---
    removePackageCommands(pkg, collisionHome, "claude");
    assert.ok(
      fs.existsSync(path.join(collisionHome, "commands", "char-test-cmd.md")),
      "removePackageCommands must refuse to delete a non-generated live command file",
    );
  } finally {
    fs.rmSync(genDir, { recursive: true, force: true });
  }
} finally {
  fs.rmSync(tmp, { recursive: true, force: true });
}

console.log("slash-commands-characterization-check: ok");
